/* Шрифт DejaVuSans (subset: латиница+кириллица+цифры) для jsPDF — поддержка русского в PDF перемещения */
(function(){
  function reg(){
    if(!window.jspdf||!window.jspdf.jsPDF) return false;
    var API=window.jspdf.jsPDF.API;
    API.events.push(['initialized', function(){
      this.addFileToVFS('DejaVuSans.ttf', '');
      this.addFont('DejaVuSans.ttf','DejaVuSans','normal');
      this.addFileToVFS('DejaVuSans-Bold.ttf', '');
      this.addFont('DejaVuSans-Bold.ttf','DejaVuSans','bold');
    }]);
    return true;
  }
  if(!reg()){
    // jsPDF ещё не загружен — ждём
    var t=setInterval(function(){ if(reg()) clearInterval(t); },50);
    setTimeout(function(){ clearInterval(t); },10000);
  }
})();
